  ('00eee48a-d7c1-4438-b4b0-65c4652fcde9', 11, '15ef7eb9-95e2-49b0-802c-f21045d4c99f', 'unit', 'Chemistry Unit Test', 'Covers Atomic Structure and Periodic Properties of the Elements, Chemical Bonding.', null, null, 15, false, null, 4),
  ('899265d6-f305-4728-8dfd-ee49d67f2f36', 11, '4d23d01c-4602-43bc-b470-194dd5d1b3a7', 'unit', 'Biology Unit Test', 'Covers Enzymes, Genetics.', null, null, 15, false, null, 5),
  ('e9a43207-4ae0-43ab-9c1e-d2043e7e86a0', 11, null, 'mock', 'Grade 11 Mock Test 1', 'Mixed questions from every subject, timed like the real exam.', null, null, 15, true, '2026-09-15', 1),
